/**
 * Switch Node - Version 3.3
 * Discriminator: mode=rules
 */


/** Build a matching rule for each output */
export type SwitchV33RulesParams = {
  /**
   * <patterns>
   * <pattern title="Switch with two cases plus a default branch">
   * const routeByPriority = switchCase({
   *   version: 3.2,
   *   config: {
   *     name: 'Route by Priority',
   *     parameters: {
   *       rules: {
   *         values: [
   *           {
   *             outputKey: 'urgent',
   *             conditions: {
   *               options: { caseSensitive: false, leftValue: '', typeValidation: 'strict' },
   *               conditions: [{ leftValue: expr('{{ $json.priority }}'), operator: { type: 'string', operation: 'equals' }, rightValue: 'urgent' }],
   *               combinator: 'and'
   *             }
   *           },
   *           {
   *             outputKey: 'normal',
   *             conditions: {
   *               options: { caseSensitive: false, leftValue: '', typeValidation: 'strict' },
   *               conditions: [{ leftValue: expr('{{ $json.priority }}'), operator: { type: 'string', operation: 'equals' }, rightValue: 'normal' }],
   *               combinator: 'and'
   *             }
   *           }
   *         ]
   *       },
   *       options: {
   *         fallbackOutput: 'extra',
   *         renameFallbackOutput: 'Fallback'
   *       }
   *     }
   *   }
   * });
   * 
   * export default workflow('id', 'name')
   *   .add(startTrigger)
   *   .to(routeByPriority
   *     .onCase(0, processUrgent.to(notifyTeam))
   *     .onCase(1, processNormal)
   *     .onCase(2, archive));
   * </pattern>
   * </patterns>
   */
  mode: 'rules';
/**
 * Routing Rules
 * @builderHint Use `rules.values` (NOT `rules.rules`). Each rule needs `outputKey` and a complete `conditions` object with these three sibling keys: `combinator` ('and' | 'or'), `conditions` (array of condition objects), `options` (`{ caseSensitive, leftValue, typeValidation }`). Same shape as IF. Wire rule outputs by zero-based index with `.onCase(index, target)`; `outputKey` is the visible output label, not the `.onCase()` argument. Unwired cases silently drop their items. Default `caseSensitive: false` for string equality, only set `true` when specifically requested or confirmed by the user.
 * @default {"values":[{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict"},"conditions":[{"leftValue":"","rightValue":"","operator":{"type":"string","operation":"equals"}}],"combinator":"and"}}]}
 */
    rules?: {
        /** Routing Rule
     */
    values?: Array<{
      /** Conditions
       * @default {}
       */
      conditions?: FilterValue;
      /** Rename Output
       * @default false
       */
      renameOutput?: boolean | Expression<boolean>;
      /** The label of output to which to send data to if rule matches
       * @displayOptions.show { renameOutput: [true] }
       */
      outputKey?: string | Expression<string>;
    }>;
  };
/**
 * If the type of an expression doesn't match the type of the comparison, n8n will try to cast the expression to the required type. E.g. for booleans &lt;code&gt;"false"&lt;/code&gt; or &lt;code&gt;0&lt;/code&gt; will be cast to &lt;code&gt;false&lt;/code&gt;
 * @default false
 */
    looseTypeValidation?: boolean | Expression<boolean>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** If no rule matches the item will be sent to this output, by default they will be ignored
     * @builderHint Set this to `'extra'` before wiring a catch-all/default branch. In rules mode, `'extra'` creates a fallback output at index `rules.values.length`; default `'none'` creates no fallback output and drops unmatched items. Numeric values route unmatched items to an existing rule output and do not create a new port.
     * @loadOptionsMethod getFallbackOutputOptions
     * @default none
     */
    fallbackOutput?: string | Expression<string>;
    /** Whether to ignore letter case when evaluating conditions
     * @default true
     */
    ignoreCase?: boolean | Expression<boolean>;
    /** If the type of an expression doesn't match the type of the comparison, n8n will try to cast the expression to the required type. E.g. for booleans &lt;code&gt;"false"&lt;/code&gt; or &lt;code&gt;0&lt;/code&gt; will be cast to &lt;code&gt;false&lt;/code&gt;
     * @default true
     */
    looseTypeValidation?: boolean | Expression<boolean>;
    /** Rename Fallback Output
     * @builderHint Only labels the extra fallback output. Use it together with `fallbackOutput: 'extra'`; it does not create a fallback output by itself.
     * @displayOptions.show { fallbackOutput: ["extra"] }
     */
    renameFallbackOutput?: string | Expression<string>;
    /** Whether to send data to all outputs meeting conditions (and not just the first one)
     * @default false
     */
    allMatchingOutputs?: boolean | Expression<boolean>;
  };
};

export type SwitchV33RulesNode = {
  type: 'n8n-nodes-base.switch';
  version: 3.3;
  config: NodeConfig<SwitchV33RulesParams>;
};